/**
 * The skins the Upgrader offers until the site has a live price feed:
 * well-known CS2 skins across every price band, one wear each, priced in
 * coins. `image` is Steam's own render of the skin, the one every case
 * site shows; `kind` picks the drawn silhouette that stands in for it
 * while it loads or where it can't be fetched.
 */

export type Wear = "FN" | "MW" | "FT" | "WW" | "BS";
export type Kind = "rifle" | "sniper" | "pistol" | "smg" | "heavy" | "knife" | "gloves";

export type Skin = {
  slug: string;
  name: string;
  weapon: string;
  finish: string;
  wear: Wear;
  price: number;
  rarity: string;
  /** The rarity's colour, as the game shows it. */
  color: string;
  kind: Kind;
  image: string;
};

export const WEARS: Record<Wear, string> = { FN: "Factory New", MW: "Minimal Wear", FT: "Field-Tested", WW: "Well-Worn", BS: "Battle-Scarred" };

